/** I01-R-ARCHGBNP: registro de texto de GBNP; solo los de indicador #ICACC# son detalle. */
public record TasaGbnpRecord(
        String indicador,        // X(07)  "#ICACC#" = detalle
        String codigo,           // X(04)
        String sucursal,         // TASA-CTA REDEFINES: espacio 9(04) + sucursal 9(04) ...
        String contrato,         // ... + contrato 9(12); String para conservar ceros
        String producto,         // X(04)
        LocalDate fecha,         // 9(08) AAAAMMDD
        String ude,              // X(15)
        String tasaTexto,        // X(24)  se convierte en TasaGbnpParser
        String rcode) {          // X(10)

    public boolean esDetalle() { return "#ICACC#".equals(indicador); }

    static final FixedLengthTokenizer TOKENIZER = new FixedLengthTokenizer();
    static {
        TOKENIZER.setNames("ind", "code", "tilde1", "space", "suc", "cto", "accpr", "prod",
                           "acceff", "fec", "accude", "ude", "tilde2", "tasa", "rcode");
        TOKENIZER.setColumns(new Range(1, 7), new Range(8, 11), new Range(12, 12),
                new Range(13, 16), new Range(17, 20), new Range(21, 32), new Range(33, 39),
                new Range(40, 43), new Range(44, 53), new Range(54, 61), new Range(62, 69),
                new Range(70, 84), new Range(85, 85), new Range(86, 109), new Range(110, 119));
        TOKENIZER.setStrict(false);                    // FILLER X(153) al final
    }
}

/** I02-R-ARCHRSLT (120 bytes): un renglón por contrato procesado, con o sin error. */
public record ResultadoTasaRecord(
        int tipoRegistro,          // 9(02)
        String sucursal,           // 9(04)
        String contrato,           // 9(12)
        int secuencia,             // 9(02)  1, 2 o 3 (corrida del día)
        long tasa,                 // 9(10)  tasa con 6 decimales implícitos (WS-TASA-CONV-N)
        int tipoInteres,           // 9(02)  0 mensual, 1 diario
        int codigoError,           // 9(04)  0 o 1001..1014
        int producto, int instrumento, int moneda,
        long tasaAplicada,         // RATE-U 9(10): tasa bruta B03 x 1 000 000
        long rendimiento,          // REND-N 9(16)
        int pasoTasa,              // PAGO-S 9(02)
        LocalDate fechaTasa) {     // FECH-S 9(08)

    public BigDecimal tasaDecimal() {
        return BigDecimal.valueOf(tasa, 6);    // 9(04)V9(06) -> escala 6
    }
}
